function Pieza({
  id,
  alto,
  label,
  className,
}: {
  id: string;
  alto: number;
  label: string;
  className: string;
}) {
  return (
    <svg
      viewBox={`0 0 100 ${alto}`}
      role="img"
      aria-label={label}
      className={className}
    >
      <use href={`#${id}`} width="100" height={alto} />
    </svg>
  );
}

/** El símbolo del infinito. */
export function Brandmark({ className = "" }: { className?: string }) {
  return (
    <Pieza id={MARCA_ID} alto={ALTO.marca} label="Inkfinity" className={className} />
  );
}

/** El nombre «Inkfinity» en su tipografía de pincel. */
export function BrandWordmark({ className = "" }: { className?: string }) {
  return (
    <Pieza id={WORDMARK_ID} alto={ALTO.nombre} label="Inkfinity" className={className} />
  );
}

/** El rótulo de la línea «Culture Fit». */
export function CultureFitMark({ className = "" }: { className?: string }) {
  return (
    <Pieza id={CULTURE_ID} alto={ALTO.linea} label="Culture Fit" className={className} />
  );
}

/** Marca + nombre, para el encabezado y el pie. */
export function Wordmark({
  tagline,
  className = "",
}: {
  tagline?: string;
  className?: string;
}) {
  return (
    <span className={`flex items-center gap-3 ${className}`}>
      <Brandmark className="h-9 w-9 shrink-0" />
      <span className="flex flex-col gap-1">
        <BrandWordmark className="w-[6.6rem]" />
        {tagline ? (
          <span className="text-[0.55rem] uppercase tracking-[0.3em] text-dim">
            {tagline}
          </span>
        ) : null}
      </span>
    </span>
  );
}
